messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background: #000; }
        canvas { display: block; }
        #info {
            position: absolute;
            top: 20px;
            width: 100%;
            text-align: center;
            color: white;
            font-family: 'Arial', sans-serif;
            font-size: 24px;
            font-weight: bold;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.8);
            pointer-events: none;
            z-index: 10;
        }
    </style>
</head>
<body>
    <div id="info">🏁 RACE 🏁</div>

    <script type="importmap">
    {
        "imports": {
            "three": "./three.module.js"
        }
    }
    </script>

    <script type="module">
        import * as THREE from './three.module.js';

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 50, 200);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        dirLight.shadow.camera.near = 0.5;
        dirLight.shadow.camera.far = 100;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeometry = new THREE.PlaneGeometry(200, 1000);
        const groundMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x3a7d3a, // Grass green
            roughness: 0.8 
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.1; // Slightly below 0 to avoid z-fighting with track
        ground.receiveShadow = true;
        scene.add(ground);

        // Track
        const trackWidth = 12;
        const trackLength = 200;
        const trackGeometry = new THREE.PlaneGeometry(trackWidth, trackLength);
        const trackMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x333333, // Dark gray asphalt
            roughness: 0.9 
        });
        const track = new THREE.Mesh(trackGeometry, trackMaterial);
        track.rotation.x = -Math.PI / 2;
        track.position.set(0, 0, -trackLength/2 + 10);
        track.receiveShadow = true;
        scene.add(track);

        // Finish Line
        const finishZ = -60;
        const finishGeometry = new THREE.PlaneGeometry(trackWidth, 2);
        // Checkered pattern using canvas texture
        const canvas = document.createElement('canvas');
        canvas.width = 64;
        canvas.height = 64;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, 64, 64);
        ctx.fillStyle = '#000000';
        ctx.fillRect(0, 0, 32, 32);
        ctx.fillRect(32, 32, 32, 32);
        const finishTexture = new THREE.CanvasTexture(canvas);
        finishTexture.wrapS = THREE.RepeatWrapping;
        finishTexture.wrapT = THREE.RepeatWrapping;
        finishTexture.repeat.set(8, 1);

        const finishMaterial = new THREE.MeshStandardMaterial({ 
            map: finishTexture,
            roughness: 0.5 
        });
        const finishLine = new THREE.Mesh(finishGeometry, finishMaterial);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.01, finishZ);
        scene.add(finishLine);

        // Finish Line Posts
        const postGeometry = new THREE.BoxGeometry(0.5, 4, 0.5);
        const postMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const leftPost = new THREE.Mesh(postGeometry, postMaterial);
        leftPost.position.set(-trackWidth/2 - 0.25, 2, finishZ);
        leftPost.castShadow = true;
        scene.add(leftPost);
        const rightPost = new THREE.Mesh(postGeometry, postMaterial);
        rightPost.position.set(trackWidth/2 + 0.25, 2, finishZ);
        rightPost.castShadow = true;
        scene.add(rightPost);

        // Banner
        const bannerGeometry = new THREE.BoxGeometry(trackWidth + 1, 1, 0.5);
        const bannerMaterial = new THREE.MeshStandardMaterial({ color: 0xff0000 });
        const banner = new THREE.Mesh(bannerGeometry, bannerMaterial);
        banner.position.set(0, 4.5, finishZ);
        banner.castShadow = true;
        scene.add(banner);

        // --- Car Creation Function ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeometry = new THREE.BoxGeometry(2, 0.5, 4);
            const chassisMaterial = new THREE.MeshStandardMaterial({ 
                color: color, 
                roughness: 0.3, 
                metalness: 0.6 
            });
            const chassis = new THREE.Mesh(chassisGeometry, chassisMaterial);
            chassis.position.y = 0.5;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeometry = new THREE.BoxGeometry(1.8, 0.4, 2);
            const cabinMaterial = new THREE.MeshStandardMaterial({ 
                color: 0x333333, // Dark gray/black windows
                roughness: 0.1, 
                metalness: 0.8 
            });
            const cabin = new THREE.Mesh(cabinGeometry, cabinMaterial);
            cabin.position.set(0, 0.9, -0.2);
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeometry = new THREE.CylinderGeometry(0.4, 0.4, 0.3, 16);
            const wheelMaterial = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const wheelPositions = [
                { x: -1, y: 0.4, z: 1.2 },
                { x: 1, y: 0.4, z: 1.2 },
                { x: -1, y: 0.4, z: -1.2 },
                { x: 1, y: 0.4, z: -1.2 }
            ];

            wheelPositions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeometry, wheelMaterial);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, pos.y, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            // Spoiler
            const spoilerGeometry = new THREE.BoxGeometry(2, 0.1, 0.5);
            const spoilerMaterial = new THREE.MeshStandardMaterial({ color: color });
            const spoiler = new THREE.Mesh(spoilerGeometry, spoilerMaterial);
            spoiler.position.set(0, 1.0, -1.8);
            carGroup.add(spoiler);

            const spoilerSupportL = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.3, 0.1), chassisMaterial);
            spoilerSupportL.position.set(-0.8, 0.85, -1.8);
            carGroup.add(spoilerSupportL);
            const spoilerSupportR = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.3, 0.1), chassisMaterial);
            spoilerSupportR.position.set(0.8, 0.85, -1.8);
            carGroup.add(spoilerSupportR);

            return carGroup;
        }

        // --- Cars ---
        const redCar = createCar(0xff0000);
        redCar.position.set(-2, 0, 20); // Start position (Z is forward towards negative)
        scene.add(redCar);

        const blueCar = createCar(0x0000ff);
        blueCar.position.set(2, 0, 20);
        scene.add(blueCar);

        // --- Animation Logic ---
        const finishLineZ = finishZ;
        const startZ = 20;

        // Race parameters
        // Blue starts faster, Red accelerates later
        let raceTime = 0;
        let redSpeed = 0;
        let blueSpeed = 0;
        let raceActive = true;
        let resetPhase = false;

        // Camera setup
        camera.position.set(0, 15, 30);
        camera.lookAt(0, 0, 10);

        function updateRace(delta) {
            if (!raceActive) {
                if (resetPhase) {
                    // Reset positions
                    redCar.position.z = startZ;
                    blueCar.position.z = startZ;
                    redCar.position.x = -2;
                    blueCar.position.x = 2;

                    // Reset speeds
                    redSpeed = 0;
                    blueSpeed = 0;
                    raceTime = 0;

                    resetPhase = false;
                    raceActive = true;
                }
                return;
            }

            raceTime += delta;

            // Speed profiles
            // Blue car: Fast start, then constant speed
            // Red car: Slow start, then accelerates

            const blueBaseSpeed = 15;
            const redBaseSpeed = 20; // Red is faster top speed

            // Blue speed: starts high, stays constant
            blueSpeed = blueBaseSpeed;

            // Red speed: accelerates over time
            // Using a sigmoid-like curve for acceleration
            const redAccelerationFactor = Math.min(raceTime * 0.5, 1); // Accelerates for first ~2 seconds of race time (scaled)
            redSpeed = 10 + (redBaseSpeed - 10) * redAccelerationFactor;

            // Update positions
            redCar.position.z -= redSpeed * delta;
            blueCar.position.z -= blueSpeed * delta;

            // Wobble effect for realism
            redCar.position.x = -2 + Math.sin(raceTime * 5) * 0.1;
            blueCar.position.x = 2 + Math.cos(raceTime * 4) * 0.1;

            // Rotate wheels
            redCar.children.forEach(child => {
                if (child.geometry && child.geometry.type === 'CylinderGeometry') {
                    child.rotation.x += 10 * delta;
                }
            });
            blueCar.children.forEach(child => {
                if (child.geometry && child.geometry.type === 'CylinderGeometry') {
                    child.rotation.x += 10 * delta;
                }
            });

            // Check finish line
            if (redCar.position.z <= finishLineZ || blueCar.position.z <= finishLineZ) {
                // Determine winner (whoever crossed first, simplified: check current positions)
                // Actually, since we update continuously, we need to track who crossed first.
                // For simplicity, let's say if red is ahead at finish, red wins.
                // But to make it loop properly, we just reset when both cross or one crosses.

                if (redCar.position.z <= finishLineZ && blueCar.position.z <= finishLineZ) {
                    raceActive = false;
                    resetPhase = true;
                }
            }
        }

        function updateCamera() {
            // Calculate midpoint between cars
            const midZ = (redCar.position.z + blueCar.position.z) / 2;
            const midX = (redCar.position.x + blueCar.position.x) / 2;

            // Camera follows the midpoint, keeping distance
            const targetZ = midZ - 15; // Behind the cars
            const targetY = 12; // Height

            // Smooth camera movement
            camera.position.z += (targetZ - camera.position.z) * 0.05;
            camera.position.y += (targetY - camera.position.y) * 0.05;
            camera.position.x += (midX * 0.5 - camera.position.x) * 0.05;

            // Look at the midpoint between cars
            const lookTarget = new THREE.Vector3(midX, 0, midZ);
            camera.lookAt(lookTarget);
        }

        // --- Main Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const delta = Math.min(clock.getDelta(), 0.1); // Cap delta to prevent huge jumps

            updateRace(delta);
            updateCamera();

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
